import requests

TIMEOUT = (5, 30)


def fetch_page(session, url, cursor=None):
    resp = session.get(url, params={"cursor": cursor}, timeout=TIMEOUT)
    resp.raise_for_status()
    return resp.json()


def paginate(session, url, state):
    cursor = state.get("cursor")
    while True:
        page = fetch_page(session, url, cursor)
        yield from page["items"]
        cursor = page.get("next_cursor")
        if not cursor:
            break
        state["cursor"] = cursor

