from pyspark.sql import functions as F, Window

SHUFFLE_PARTITIONS = 400


def sessionize(events, gap_minutes=30):
    w = Window.partitionBy("customer_id").orderBy("event_ts")
    gap = F.col("event_ts").cast("long") - F.lag("event_ts").over(w).cast("long")
    return events.withColumn("new_session", (gap > gap_minutes * 60).cast("int"))

