def row_count_check(table, ds, history, floor=0.7):
    median = sorted(history)[len(history) // 2]
    return table.rows(ds) >= floor * median


def run_checks(table, ds, checks):
    failed = [c.name for c in checks if not c.run(table, ds)]
    if failed:
        quarantine(table, ds)
    return failed

