import hmac, hashlib


def mask_email(value):
    local, _, domain = value.partition("@")
    return local[:1] + "***@" + domain


def tokenize(value, key):
    return hmac.new(key, value.strip().lower().encode(), hashlib.sha256).hexdigest()

