import time


def with_retry(attempts=3, base=2.0, cap=1200, retry_on=(TimeoutError,)):
    def wrap(fn):
        def inner(*a, **kw):
            for n in range(attempts):
                try:
                    return fn(*a, **kw)
                except retry_on:
                    time.sleep(min(cap, base ** n))
            return fn(*a, **kw)
        return inner
    return wrap
